styles.beforeSource:
#nwSiteLoader{display:none!important;visibility:hidden!important;pointer-events:none!important;}
html body.nw-app-loading #app,html body.nw-app-loading #topBanner{opacity:1!important;pointer-events:auto!important;}
html body.nw-app-ready #app,html body.nw-app-ready #topBanner{animation:none!important;filter:none!important;}
html body[data-county-viewport] #leftPanel,html body[data-county-viewport] #rightRail,html body[data-county-viewport] #timelineDock,html body[data-county-viewport] #timelineBubble{transition:none!important;animation:none!important;}

@layer floodmapper-unified-polish {
/* Readiness belongs to the flood/data renderer, not a branded page transition. */
html body #nwSiteLoader{display:none!important;visibility:hidden!important;pointer-events:none!important;}
html body:is(.nw-app-loading,.nw-app-ready) :is(#app,#topBanner){
 opacity:1!important;pointer-events:auto!important;animation:none!important;filter:none!important;
}
}

styles.afterSource:
@layer floodmapper-unified-polish {
/* The welcome overlay follows renderer readiness; controls reveal without a second transition. */
html body.nw-app-ready:not(.nw-app-loading) :is(#app,#topBanner){
 opacity:1!important;pointer-events:auto!important;animation:none!important;filter:none!important;
}
}
